def get_2d2mesh_repair_patch(original_gitignore: Optional[str] = None) -> str:
    """
    Constructs the canonical 15-file unified diff patch for 2D2Mesh:
    1. Fixes .gitignore unanchored models/ -> /models/ and removes merge conflict markers.
    2. Restores all 8 authentic domain models in backend/app/models/.
    3. Restores all 6 authentic AI models in backend/app/ai/models/.
    """
    orig_gi = original_gitignore if original_gitignore is not None else DEFAULT_ORIGINAL_GITIGNORE
    gi_diff = "".join(difflib.unified_diff(
        orig_gi.splitlines(keepends=True),
        FIXED_GITIGNORE.splitlines(keepends=True),
        fromfile="a/.gitignore",
        tofile="b/.gitignore"
    )).strip()

    patch_parts = [gi_diff] if gi_diff else []

    for rel_path, content in RECOVERED_2D2MESH_FILES.items():
        file_diff = "".join(difflib.unified_diff(
            [],
            content.splitlines(keepends=True),
            fromfile="/dev/null",
            tofile=f"b/{rel_path}"
        )).strip()
        if file_diff:
            patch_parts.append(file_diff)

    return "\n\n".join(patch_parts) + "\n"


def verify_2d2mesh_models_present(workspace_path: str) -> Tuple[bool, List[str]]:
    """
    Verifies that all 14 required modules and .gitignore exist in workspace_path.
    Returns (is_complete, missing_files).
    """
    missing: List[str] = []
    for rel_path in RECOVERED_2D2MESH_FILES.keys():
        disk_p = os.path.join(workspace_path, rel_path.replace("/", os.sep))
        if not os.path.isfile(disk_p):
            missing.append(rel_path)
    return len(missing) == 0, missing
